#include <cstdio>
#include <algorithm>
#include <vector>
#include <stack>

using namespace std;

int get_input()
{
    int val;
    scanf("%d",&val);
    return val;
}

bool visited_nodes[1000007];
const int MOD_CONST=1000000007;
long long divisor_counts[1000007];
long long cycle_lengths[1000007];
long long dp_array[1000007];

int main()
{
    long long answer=1;
    int total_p, total_k;
    total_p=get_input();
    total_k=get_input();
    for(int i=0; i<total_p; i++)
    {
        if(!visited_nodes[i])
        {
            int length=0;
            long long current=i;
            while(!visited_nodes[current])
            {
                visited_nodes[current]=1;
                current=((long long)total_k*current)%total_p;
                length++;
            }
            cycle_lengths[length]++;
        }
    }
    for(int i=1; i<=total_p; i++)
    {
        dp_array[i]=((long long)cycle_lengths[i]*i)%MOD_CONST;
    }
    for(int i=1; i<=total_p; i++)
    {
        divisor_counts[i]=(divisor_counts[i]+dp_array[i])%MOD_CONST;
        for(int j=i+i; j<=total_p; j+=i)
        {
            divisor_counts[j]=(dp_array[i]+divisor_counts[j])%MOD_CONST;
        }
    }
    for(int i=1; i<=total_p; i++)
    {
        if(i==1)
        {
            for(int j=0; j<cycle_lengths[i]-1; j++)
                answer=(answer*(long long)cycle_lengths[i])%MOD_CONST;
        }
        else
        {
            for(int j=0; j<cycle_lengths[i]; j++)
                answer=(answer*(long long)divisor_counts[i])%MOD_CONST;
        }
    }
    if(total_k==1) answer=(answer*divisor_counts[1])%MOD_CONST;
    printf("%lld", answer);
    return 0;
}
